import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { orderService } from '../../services/orderService';
import './MyOrders.css';

const fmt = (value) =>
  Number(value || 0).toLocaleString('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 });

const MyOrders = () => {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    orderService.getMyOrders().then(setOrders).finally(() => setLoading(false));
  }, []);

  if (loading) {
    return (
      <div className="my-orders-page container">
        <h1>My Orders</h1>
        <p>Loading orders...</p>
      </div>
    );
  }

  // Get timeline steps based on order status
  const getTimelineSteps = (status) => {
    const steps = [
      { id: 'ordered', label: 'Ordered', icon: '📦' },
      { id: 'processing', label: 'Processing', icon: '⚙️' },
      { id: 'shipped', label: 'Shipped', icon: '🚚' },
      { id: 'delivered', label: 'Delivered', icon: '✅' }
    ];

    const statusOrder = {
      'pending': 0,
      'processing': 1,
      'shipped': 2,
      'delivered': 3,
      'cancelled': -1,
      'returned': -1
    };

    const currentStep = statusOrder[status] || 0;

    return steps.map((step, index) => ({
      ...step,
      completed: index < currentStep,
      active: index === currentStep
    }));
  };

  return (
    <div className="my-orders-page container">
      <h1>My Orders</h1>

      {orders.length === 0 ? (
        <div className="empty-state">
          <h3>No orders found</h3>
          <p>You haven't placed any orders yet</p>
          <Link to="/products" className="btn btn-primary">Start Shopping</Link>
        </div>
      ) : (
        <div className="orders-list">
          {orders.map(order => (
            <div className="order-card" key={order._id}>
              <div className="order-header">
                <div>
                  <span className="order-id">Order #{order.orderNumber || order._id?.toString().slice(-8)}</span>
                  <span className="order-date">Placed on {new Date(order.createdAt).toLocaleDateString()}</span>
                </div>
                <span className={`order-status ${order.status.toLowerCase()}`}>
                  {order.status}
                </span>
              </div>

              <div className="order-items">
                {(order.vendorOrders ? order.vendorOrders.flatMap(v => v.items || []) : (order.products || [])).map((p, idx) => (
                  <div className="order-item" key={`${order._id}-${idx}`}>
                    <img 
                      src={p.image || (p.images && p.images[0]?.url) || '/placeholder.png'} 
                      alt={p.name} 
                    />
                    <div className="order-item-info">
                      <Link to={`/products/${p.product || p._id}`}>{p.name}</Link>
                      <span>{fmt(p.price)}</span>
                    </div>
                  </div>
                ))}
              </div>

              {/* Order Timeline */}
              {order.status !== 'cancelled' && order.status !== 'returned' && (
                <div className="order-timeline">
                  <div className="timeline-title">Order Status</div>
                  <div className="timeline-steps">
                    {getTimelineSteps(order.status).map(step => (
                      <div 
                        className={`timeline-step ${step.completed ? 'completed' : ''} ${step.active ? 'active' : ''}`} 
                        key={step.id}
                      >
                        <div className="step-icon">{step.icon}</div>
                        <span className="step-label">{step.label}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              <div className="order-footer">
                <span>Total: {fmt(order.totalAmount || order.total)}</span>
                <div className="order-actions">
                  <Link to={`/track/${order._id || order.orderId}`} className="btn btn-outline btn-sm">
                    Track Order
                  </Link>
                  <Link to="/products" className="btn btn-outline btn-sm">
                    Buy Again
                  </Link>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default MyOrders;
